def stirling2(n, k):
    # using recurrence
    S = [[0]*(k+1) for _ in range(n+1)]
    S[0][0] = 1
    for i in range(1, n+1):
        for j in range(1, k+1):
            S[i][j] = j*S[i-1][j] + S[i-1][j-1]
    return S[n][k]

