def black_scholes(S, K, r, sigma, T, option_type='call'):
    d1 = (log(S/K) + (r + 0.5*sigma**2)*T) / (sigma*sqrt(T))
    d2 = d1 - sigma*sqrt(T)
    N = NormalDist().cdf
    if option_type == 'call':
