    total = sum(random.randint(1, 6) for _ in range(3))
    if 3 <= total <= 10:
        return 0
    elif 11 <= total <= 16:
        return 10
    elif 17 <= total <= 22:
        return 20
    elif 23 <= total <= 28:
        return 30
    elif 29 <= total <= 34:
        return 40
    elif 35 <= total <= 40:
        return 50

print(roll_three_dice_points())

